contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint withdrawAmount) public payable {
        require(amount > 0);
        require(withdrawAmount > 0);
        require(address(this).balance >= amount);

        c.deposit{value: amount}();
        uint creditedBefore = c.credit(address(this));
        uint balanceBefore = address(c).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

