contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // deposit amount into c
        c.deposit{value: amount}();

        // read c's balance after deposit
        uint balanceAfterDeposit = address(c).balance;

        // record this contract's balance before withdrawal
        uint balanceBeforeWithdraw = address(this).balance;

        // withdraw all credited Ether
        c.withdrawAll();

        // read c's balance after withdrawal
        uint balanceAfterWithdraw = address(c).balance;

        // observe credit through the public getter
        uint creditAfter = c.credit(address(this));

        // general rule: after deposit and withdraw, c's balance decreased by amount,
        // this contract's balance increased by amount, and credit is zero
        assert(
            balanceAfterWithdraw + amount == balanceAfterDeposit &&
            address(this).balance == balanceBeforeWithdraw + amount &&
            creditAfter == 0
        );
    }

    receive() external payable {}
}

