    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        c.deposit{value: amount}();
        uint balAfterDeposit = address(c).balance;

        uint creditBeforeWithdraw = uint(keccak256(abi.encodePacked(address(this), uint(0)))) * 0;
        // credit is private, so we use a separate call to observe indirectly by depositing 0
        // Actually credit has no getter, so we cannot read it directly.
        // We can only observe credit through effects of withdrawAll.
        creditBeforeWithdraw = 0; // placeholder, not used

        bool withdrew;
        try c.withdrawAll() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        if (withdrew) {
            uint balAfterWithdraw = address(c).balance;
            // After successful deposit and successful withdrawAll,
            // c's balance decreases by exactly the deposit amount,
            // and the caller's credit becomes zero (observable via a second withdrawAll being a no-op).
            assert(balAfterWithdraw + amount == balAfterDeposit);
            uint balBeforeSecond = address(c).balance;
            c.withdrawAll();
            assert(address(c).balance == balBeforeSecond);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

