            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(address(c).balance == balanceAfterDeposits);
            assert(address(c).balance >= expectedCredit);
        } else {
            assert(address(c).balance == balanceAfterDeposits - expectedCredit);
        }
    }

    receive() external payable {}
}

